"use strict";(globalThis.webpackChunkgrc||=[]).push([[40012],{14114(e){e.exports=JSON.parse('{"citeKey":"logan2021pmemcpy","slug":"logan-2021-pmemcpy-f81c","title":"pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory","authors":["L. Logan","J. Lofstead","S. Levy","P. Widener","X.-H. Sun","A. Kougkas"],"venue":"The 1st Workshop on Re-envisioning Extreme-Scale I/O for Emerging Hybrid HPC Workloads (REX-IO\'21), in conjunction with the 2021 IEEE International Conference on Cluster Computing (CLUSTER\'21), September 7-10, 2021","type":"Workshop","entryType":"inproceedings","date":"September, 2021","year":2021,"era":"iit","month":9,"doi":"10.1109/cluster48925.2021.00098","abstract":"Persistent memory (PMEM) devices can achieve comparable performance to DRAM while providing significantly more capacity. This has made the technology compelling as an expansion to main memory. Rethinking PMEM as storage devices can offer a high performance buffering layer for HPC applications to temporarily, but safely store data. However, modern parallel I/O libraries, such as HDF5 and pNetCDF, are complicated and introduce significant software and metadata overheads when persisting data to these storage devices, wasting much of their potential. In this work, we explore the potential of PMEM as storage through pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory. We demonstrate that our approach is up to 2x faster than other popular parallel I/O libraries under real workloads.","hasAbstract":true,"lede":"We explore the potential of PMEM as storage through pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory.","links":{"pdf":"https://grc.iit.edu/papers/2021/logan-2021-pmemcpy-f81c.pdf"},"tags":["Persistent Memory","Libraries","Memory Management","Memory Mapped I/O"],"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["hermes"],"memberAuthors":["logan-luke","lofstead-jay","sun-xian-he","kougkas-anthony"]}')}}]);